<script setup>
import {ref,onMounted,onBeforeUnmount} from 'vue'
import {request} from './client'
const props=defineProps({classroom:Object}),emit=defineEmits(['close','unlocked']),dialog=ref(null),key=ref(''),lesson=ref(null),busy=ref(false),error=ref('')
async function enter(){busy.value=true;error.value='';try{await request('demo_learning','enter_classroom',{classroom:props.classroom.name,enrollment_key:key.value});window.location.assign('/campus?classroom='+encodeURIComponent(props.classroom.name)+'#classrooms')}catch(e){error.value=e.message}finally{busy.value=false}}
async function open(){busy.value=true;error.value='';try{lesson.value=await request('demo_learning','open_practice',{classroom:props.classroom.name,enrollment_key:key.value});emit('unlocked')}catch(e){error.value=e.message}finally{busy.value=false}}
onMounted(()=>{dialog.value.showModal();if(props.classroom.unlocked)open()});onBeforeUnmount(()=>dialog.value?.close())
</script>
<template><dialog ref="dialog" class="demo-lesson" aria-labelledby="demo-title" @cancel.prevent="emit('close')"><button class="close" aria-label="Close lesson" @click="emit('close')">×</button><small>FICTIONAL SISU DEMO</small><h2 id="demo-title">{{classroom.title}}</h2><p v-if="error" role="alert">{{error}}</p><p v-if="busy" role="status">Opening your lesson…</p><template v-if="lesson"><p class="practice-body">{{lesson.body}}</p><p>{{lesson.notice}}</p><p>Register with the demo institute first to enter its full classroom.</p><button class="button primary" :disabled="busy" @click="enter">View classroom</button></template><form v-else-if="!classroom.unlocked" @submit.prevent="open"><p>Try the locked-class experience with the demo enrollment key <strong>SISU-DEMO</strong>. No payment is needed or collected.</p><label>Demo enrollment key<input v-model="key" required maxlength="40" autocomplete="off"></label><button class="button primary" :disabled="busy||!key.trim()">Unlock demo lesson</button></form></dialog></template>
<style scoped>.demo-lesson{position:fixed;inset:0;margin:auto;width:min(570px,calc(100vw - 32px));border:1px solid #dbd0e9;border-radius:24px;padding:30px;background:white;color:#392548;max-height:90vh;overflow:auto}.demo-lesson::backdrop{background:#26123888}.demo-lesson p{line-height:1.8}.demo-lesson label{display:grid;gap:8px;margin:20px 0}.demo-lesson input{padding:12px;border:1px solid #cbbbdc;border-radius:10px}.close{position:absolute;right:14px;top:10px;font-size:24px;background:none;border:0}.practice-body{padding:22px;background:#f4f0fb;border-radius:16px}</style>
